<section class="section-heading"><div><h2>Prepare a seasonal front page</h2><p>Scheduling is disabled pending approval. Drafts are stored and cancellation is logged; no timer, job or request activates them.</p></div><span class="pill">AUTOMATIC ACTIVATION DISABLED</span></section><form method="post" class="studio-panel"><?php $hidden('schedule_save')?><label>Published login design<select name="schedule[pageId]" required><?php foreach(ag_pd_list_pages() as $p):try{ag_sa_front_candidate($p['id']);}catch(Throwable $e){continue;}?><option value="<?=ag_h($p['id'])?>"><?=ag_h($p['title'])?></option><?php endforeach ?></select></label><label>Intended grid timezone<select name="schedule[timezone]" required><?php foreach(DateTimeZone::listIdentifiers() as $zone):?><option <?=$zone===date_default_timezone_get()?'selected':''?>><?=ag_h($zone)?></option><?php endforeach ?></select></label><div class="two-column"><label>Start (in chosen timezone)<input type="datetime-local" name="schedule[start]" required></label><label>Optional end<input type="datetime-local" name="schedule[end]"></label></div><label>After end<select name="schedule[after]"><option value="previous">Restore previous active page and themes</option><option value="default">Return to native default login page</option></select></label><button>Save disabled schedule draft</button></form><?php foreach($state['schedules'] as $id=>$schedule):?><article class="studio-panel"><h3><?=ag_h(ag_pd_load_by_id($schedule['pageId'])['title'] ?? 'Unavailable page')?></h3><p><?=ag_h($schedule['status'])?> · <?=ag_h($schedule['timezone'])?> · <?=(new DateTimeImmutable('@'.$schedule['start']))->setTimezone(new DateTimeZone($schedule['timezone']))->format('Y-m-d H:i')?></p><form method="post"><?php $hidden('schedule_cancel')?><input type="hidden" name="scheduleId" value="<?=ag_h($id)?>"><button class="secondary" <?=$schedule['status']==='cancelled'?'disabled':''?>>Cancel schedule</button></form></article><?php endforeach ?>